import * as THREE from 'three';
import { MeshWrapperCommon } from '../base/MeshWrapperCommon';

import { SceneWrapper } from '..';

import { HypercubeMaterials } from './Materials';

import { Particle } from './Particle';

import { COLOR_MAP, COLOR_MAP_TYPE, MeshGradient } from './MeshGradient';
import { getSlider } from '../../../utils';

export class HypercubeSimulationViz extends MeshWrapperCommon {
	public mesh!: THREE.Mesh;

	public materials!: HypercubeMaterials;

	private _runningDroneDevices = false;

	private _visible = true;

	public clippingPlanes: THREE.Plane[] = [];
	public section: THREE.Mesh;

	public meshGradient: MeshGradient;
	public meshGradientInner: MeshGradient;
	public meshGradientServer: MeshGradient;

	public particle: Particle;

	public min: number = 0.0;
	public max: number = 1.6;

	constructor(sceneWrapper: SceneWrapper) {
		super(sceneWrapper);
		this.sceneWrapper = sceneWrapper;

		this.init();
	}
	public init() {
		this.initPart();
	}
	async initPart() {
		let urlBase = 'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/cube/'; // process.env.PUBLIC_URL;
		// let objUrlOuter = process.env.PUBLIC_URL + '/static/hypercube/model/39-outer.obj';
		let objUrlOuter = urlBase + '39-outer.obj';
		fetch(objUrlOuter)
			.then((response) => {
				if (!response.ok) {
					throw new Error('Failed to load OBJ');
				}
				return response.text();
			})
			.then((objText) => {
				this.meshGradient = new MeshGradient({ scene: this.sceneWrapper.scene });
				this.meshGradient.yOff = -2.3;
				this.meshGradient.speed = 1.25;
				this.meshGradient.min = this.min;
				this.meshGradient.max = this.max;
				this.meshGradient.initByOBJ(objText);

				this.initUI();
			})
			.catch((error) => {
				console.error(error);
			});

		let objUrlInner = urlBase + '39-inner.obj';
		// let objUrl = urlBase + '/static/hypercube/model/39-inner.obj';
		fetch(objUrlInner)
			.then((response) => {
				if (!response.ok) {
					throw new Error('Failed to load OBJ');
				}
				return response.text();
			})
			.then((objText) => {
				this.meshGradientInner = new MeshGradient({ scene: this.sceneWrapper.scene });
				this.meshGradientInner.yOff = -2.3;

				this.meshGradientInner.initByOBJ(objText, 0.001);
				this.meshGradientInner.speed = 1.1;
				this.meshGradientInner.min = this.min + 0.25;
				this.meshGradientInner.max = this.max + 0.5;

				// this.initUI()
			})
			.catch((error) => {
				console.error(error);
			});

		let objUrlServer = urlBase + '39-server.obj';
		// let objUrl = urlBase + '/static/hypercube/model/39-inner.obj';
		fetch(objUrlServer)
			.then((response) => {
				if (!response.ok) {
					throw new Error('Failed to load OBJ');
				}
				return response.text();
			})
			.then((objText) => {
				this.meshGradientServer = new MeshGradient({ scene: this.sceneWrapper.scene });
				this.meshGradientServer.yOff = -2.3;
				this.meshGradientServer.zOff = -0.2;

				this.meshGradientServer.initByOBJ(objText);
				this.meshGradientServer.speed = 1.0;
				this.meshGradientServer.min = this.min + 0.25 + 0.2;
				this.meshGradientServer.max = this.max + 0.5 + 0.5;

				// this.initUI()

				this.ready = true;
			})
			.catch((error) => {
				console.error(error);
			});

		if (!this._visible) {
			this.show(this._visible);
		}

		this.particle = new Particle(this.sceneWrapper);

		// --- 오로라 쉐이더용 풀스크린 플레인 ---
		const auroraVertex = `
    varying vec2 vUv;
    void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
  `;

		// Simplex noise function (classic implementation) and aurora color bands
		const auroraFragment = `
    precision highp float;
    varying vec2 vUv;
    uniform float time;
    uniform vec2 resolution;

    // 2D Random/Noise - IQ's classic
    vec3 mod289(vec3 x){return x - floor(x * (1.0/289.0)) * 289.0;}
    vec2 mod289(vec2 x){return x - floor(x * (1.0/289.0)) * 289.0;}
    vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}    
    float snoise(vec2 v){
      const vec4 C = vec4(0.211324865405187, 0.366025403784439, -0.577350269189626, 0.024390243902439);
      vec2 i = floor(v + dot(v, C.yy));
      vec2 x0 = v - i + dot(i, C.xx);
      vec2 i1 = (x0.x > x0.y) ? vec2(1.0,0.0) : vec2(0.0,1.0);
      vec4 x12 = x0.xyxy + C.xxzz;
      x12.xy -= i1;
      i = mod289(i);
      vec3 p = permute( permute( i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));
      vec3 m = max(0.5 - vec3(dot(x0,x0), dot(x12.xy,x12.xy), dot(x12.zw,x12.zw)), 0.0);
      m = m*m ; m = m*m ;
      vec3 x = 2.0 * fract(p * C.www) - 1.0;
      vec3 h = abs(x) - 0.5;
      vec3 ox = floor(x + 0.5);
      vec3 a0 = x - ox;
      m *= 1.79284291400159 - 0.85373472095314 * ( a0*a0 + h*h );
      vec3 g;
      g.x = a0.x * x0.x + h.x * x0.y;
      g.y = a0.y * x12.x + h.y * x12.y;
      g.z = a0.z * x12.z + h.z * x12.w;
      return 130.0 * dot(m, g);
    }

    // palette for aurora
    vec3 auroraPalette(float t){
      vec3 a = vec3(0.02,0.0,0.08);
      vec3 b = vec3(0.0,0.4,0.5);
      vec3 c = vec3(0.2,1.0,0.6);
      vec3 d = vec3(1.0,1.0,0.6);
      if(t<0.25) return mix(a,b, smoothstep(0.0,0.25, t));
      if(t<0.6) return mix(b,c, smoothstep(0.25,0.6,t));
      return mix(c,d, smoothstep(0.6,1.0,t));
    }

    void main(){
      vec2 uv = vUv;
      vec2 p = uv * vec2(resolution.x/resolution.y, 1.0);
      float t = time * 0.05;

      float n = 0.0;
      float freq = 1.0;
      float amp = 1.0;
      for(int i=0;i<5;i++){
        n += snoise(vec2(p.x*freq*2.0, p.y*freq*0.6 - t*float(i)*0.3)) * amp;
        freq *= 2.0; amp *= 0.5;
      }

      // vertical bands with smooth falloff
      float bands = smoothstep(0.1, 0.0, abs(sin((p.x*2.0 + n*0.6 + t*0.2)))) ;
      float shimmer = pow(smoothstep(-0.2,0.6, n), 2.0);
      float intensity = clamp(bands*shimmer, 0.0, 1.0);

      // create multiple layered strips
      float strip = smoothstep(0.0, 0.9, fract((p.y*4.0 + n*1.2 - t*0.6)));
      float combined = intensity * strip;

      vec3 col = auroraPalette(combined);
      // add soft glow and subtle blue background
      vec3 back = vec3(0.01,0.02,0.04) + 0.12*vec3(snoise(p*0.5 + t*0.2));
      vec3 final = mix(back, col, combined);

      // vignette
      float d = distance(uv, vec2(0.5));
      final *= smoothstep(0.9, 0.3, d);

      gl_FragColor = vec4(final, combined*0.9);
    }
  `;

		const auroraMat = new THREE.ShaderMaterial({
			vertexShader: auroraVertex,
			fragmentShader: auroraFragment,
			transparent: true,
			uniforms: {
				time: { value: 0 },
				resolution: { value: new THREE.Vector2(500, 500) },
			},
			depthWrite: false,
		});
		const auroraGeo = new THREE.PlaneGeometry(16, 9, 1, 1);
		const auroraMesh = new THREE.Mesh(auroraGeo, auroraMat);
		auroraMesh.position.set(0, 3, -2);
		auroraMesh.rotation.x = -0.25;
		this.sceneWrapper.scene.add(auroraMesh);

		// debugger

		// this.ready = true;
	}
	public get visible() {
		return this._visible;
	}
	public set visible(v) {
		this._visible = v;
	}
	public get runningDroneDevices() {
		return this._runningDroneDevices;
	}
	public set runningDroneDevices(v: boolean) {
		this._runningDroneDevices = v;
	}
	public set angleSolarPanel(v: number) {
		// console.log(v * 0.01);
		// this.solarPanel.rotate(v * 0.01);
	}
	public show(value: boolean) {}
	public showCamera() {
		this.sceneWrapper.appCore.solution.view.showCamera();
	}
	public showGraph() {
		this.sceneWrapper.appCore.solution.view.showGraph();
	}
	public showGraphDrone() {
		this.sceneWrapper.appCore.solution.view.showGraphDrone();
	}
	public update() {
		this.meshGradient?.update();
		this.meshGradientInner?.update();
		this.meshGradientServer?.update();

		this.particle?.update();

		return true;
	}
	private initUI() {
		const divUI = document.createElement('div');
		divUI.style.position = 'absolute';
		divUI.style.top = '0';
		this.sceneWrapper.appCore.rendererCore.host.appendChild(divUI);

		const slTypeSpeed = getSlider('ani speed', 0.0, 100);
		// slTypeSpeed.slider.defaultValue = '10';
		divUI.appendChild(slTypeSpeed.div);
		slTypeSpeed.slider.oninput = () => {
			const value = parseInt(slTypeSpeed.slider.value) * 0.01;
			this.meshGradient.speed = value;
		};

		const slTypeMin = getSlider(`min:${this.meshGradient.min}`, -300, 300);
		// slTypeMin.slider.defaultValue = `${this.meshGradient.min}`;
		divUI.appendChild(slTypeMin.div);
		slTypeMin.slider.oninput = () => {
			const value = parseInt(slTypeMin.slider.value) * 0.01;
			this.meshGradient.min = value;
			slTypeMin.text.textContent = `min:${value.toFixed(2)}`;
		};
		const slTypeMax = getSlider(`max:${this.meshGradient.max}`, -300, 300);
		// slTypeMax.slider.defaultValue = `${this.meshGradient.max}`;
		divUI.appendChild(slTypeMax.div);
		slTypeMax.slider.oninput = () => {
			const value = parseInt(slTypeMax.slider.value) * 0.01;
			this.meshGradient.max = value;
			slTypeMax.text.textContent = `max:${value.toFixed(2)}`;
		};

		const slTypeClippingX = getSlider(`Clipping X`, -200, 200);
		// slTypeClippingX.slider.defaultValue = `${200}`;
		divUI.appendChild(slTypeClippingX.div);
		slTypeClippingX.slider.oninput = () => {
			const value = parseInt(slTypeClippingX.slider.value) * 0.01;
			this.meshGradient.clippingX = value;
			this.meshGradientInner.clippingX = value;
			this.meshGradientServer.clippingX = value;
		};

		const slTypeClippingY = getSlider(`Clipping Y`, -200, 200);
		// slTypeClippingY.slider.defaultValue = `${200}`;
		divUI.appendChild(slTypeClippingY.div);
		slTypeClippingY.slider.oninput = () => {
			const value = parseInt(slTypeClippingY.slider.value) * 0.01;
			this.meshGradient.clippingY = value;
			this.meshGradientInner.clippingY = value;
			this.meshGradientServer.clippingY = value;
		};

		const slTypeYOffset = getSlider(`Y Off`, -50, 50);
		// slTypeYOffset.slider.defaultValue = `${200}`;
		divUI.appendChild(slTypeYOffset.div);
		slTypeYOffset.slider.oninput = () => {
			const value = parseInt(slTypeYOffset.slider.value) * 0.1;
			// this.meshGradient.clipY = value
			// this.meshGradientInner.clipY = value
			// this.meshGradientServer.clipY = value

			console.log(value);

			this.meshGradientServer.mesh.position.z = value;
		};

		const keys = Object.keys(COLOR_MAP_TYPE);
		const header = document.createElement('div');
		header.className = 'header';
		const slider = document.createElement('input');
		slider.type = 'range';
		slider.min = '0';
		slider.max = `${keys.length - 1}`;
		slider.value = '0';
		slider.style.width = '100px';

		const nameEl = document.createElement('div');
		nameEl.className = 'name';
		header.appendChild(nameEl);

		const controls = document.createElement('div');
		controls.className = 'controls';

		const hexList = document.createElement('div');
		hexList.className = 'hexList';

		// divUI에 붙이기
		divUI.appendChild(header);
		divUI.appendChild(slider);
		divUI.appendChild(controls);

		divUI.appendChild(hexList);

		// 함수
		const updateUI = () => {
			const idx = Number(slider.value);
			const key = keys[idx];
			const map = COLOR_MAP[COLOR_MAP_TYPE[key]];
			// console.log({ idx, keys, key, map });

			nameEl.textContent = key;
			// indexLabel.textContent = `${idx + 1} / ${keys.length}`;
			// const hexColors = map.map((entry) => `#${entry.color.getHexString()}`);
			// hexList.textContent = hexColors.join('  •  ');

			// console.log({ key });

			this.meshGradient.initMat(COLOR_MAP_TYPE[key]);
			this.meshGradientInner.initMat(COLOR_MAP_TYPE[key]);
			this.meshGradientServer.initMat(COLOR_MAP_TYPE[key]);
		};
		slider.addEventListener('input', updateUI);
		// updateUI();
	}
	public initPost() {
		this.sceneWrapper.appCore.common.moveTo(15, 0, 0);
		this.sceneWrapper.appCore.common.moveFrom(35, 0, 0);

		this.sceneWrapper.appCore.common.toggleHDRIBackground(false);
		this.sceneWrapper.appCore.common.backgroundColor(new THREE.Color(1, 1, 1));
		this.sceneWrapper.appCore.common.backgroundColor(new THREE.Color(0, 0, 0));
	}
}
