import { View } from '../';
import { getSlider, getDivider } from '../../utils';

export class UILeftParametric {
	public view: View;
	public width!: string;
	public divUILeft!: HTMLDivElement;
	public color!: string;

	constructor(view: View) {
		this.view = view;
	}
	public init() {
		this.uiConfigurator();
		this.view.solution.appCore.common.commandHypercubeParametric.updateLogParameters();
	}
	public uiConfigurator() {
		// const divBtnHideAll = document.createElement('button');
		// this.divUILeft.appendChild(divBtnHideAll);
		// divBtnHideAll.style.width = this.width;
		// divBtnHideAll.style.marginTop = '15px';
		// divBtnHideAll.textContent = 'Hide All';
		// divBtnHideAll.style.fontSize = this.view.fontSize;
		// divBtnHideAll.onclick = () => {
		// 	this.view.solution.appCore.common.hideAll();
		// 	this.view.solution.appCore.common.showHypercube();
		// };

		let isStudioVisible = true;
		const divBtnShowStudio = document.createElement('button');
		this.divUILeft.appendChild(divBtnShowStudio);
		divBtnShowStudio.style.marginTop = '15px';
		divBtnShowStudio.style.width = this.width;
		divBtnShowStudio.textContent = 'Show/Hide HC Static model';
		divBtnShowStudio.style.fontSize = '10px';
		divBtnShowStudio.onclick = () => {
			if (isStudioVisible) {
				this.view.solution.appCore.common.commonSandbox.showHypercubeStatic();
			} else {
				this.view.solution.appCore.common.commonSandbox.hideHypercubeStatic();
			}
			isStudioVisible = !isStudioVisible;
		};

		const initParam = this.view.solution.appCore.sceneWrapper.configurator?.hypercubeParametric?.params;
		if (initParam) {
			const divBt3 = document.createElement('button');
			this.divUILeft.appendChild(divBt3);
			divBt3.style.width = this.width;
			divBt3.textContent = 'Shifting HDRI';
			divBt3.style.marginTop = '10px';
			divBt3.style.fontSize = this.view.fontSize;
			divBt3.onclick = () => {
				this.view.solution.appCore.common.hdriChanging();
			};

			const divBtForward = document.createElement('button');
			this.divUILeft.appendChild(divBtForward);
			divBtForward.style.width = this.width;
			divBtForward.textContent = 'changing views forward';
			divBtForward.style.fontSize = '11px';
			divBtForward.onclick = () => {
				this.view.solution.appCore.common.viewChangingForward();
			};

			const divBtBackward = document.createElement('button');
			this.divUILeft.appendChild(divBtBackward);
			divBtBackward.style.width = this.width;
			divBtBackward.textContent = 'changing views backward';
			divBtBackward.style.fontSize = '11px';
			divBtBackward.onclick = () => {
				this.view.solution.appCore.common.viewChangingBackward();
			};

			const min = 10;
			const max = 60;
			const step = 0.1;
			const sliderWidth = getSlider('Width', min, max, step, initParam.width);
			this.divUILeft.appendChild(sliderWidth.div);
			sliderWidth.slider.oninput = () => {
				const value = parseFloat(sliderWidth.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setWidthParametricHC(value);
			};

			const sliderLength = getSlider('Length', min, max, step, initParam.length);
			this.divUILeft.appendChild(sliderLength.div);
			sliderLength.slider.oninput = () => {
				const value = parseFloat(sliderLength.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setLengthParametricHC(value);
			};

			const sliderHeight = getSlider('Height', min, max, step, initParam.height);
			this.divUILeft.appendChild(sliderHeight.div);
			sliderHeight.slider.oninput = () => {
				const value = parseFloat(sliderHeight.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setHeightParametricHC(value);
			};

			let minParam = 0;
			let maxParam = 10;
			let scaleParam = 0.01;
			const debuggerSetHeight = getSlider('Disco ball degree', minParam, maxParam);
			debuggerSetHeight.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerSetHeight.div);
			debuggerSetHeight.slider.oninput = () => {
				const value = parseFloat(debuggerSetHeight.slider.value);
				this.view.solution.appCore.common.debuggerHeight(value);
			};

			const divBtnGizmo = document.createElement('button');
			this.divUILeft.appendChild(divBtnGizmo);
			divBtnGizmo.style.marginTop = '15px';
			divBtnGizmo.style.width = this.width;
			divBtnGizmo.textContent = 'Gizmo';
			divBtnGizmo.style.fontSize = '10px';
			divBtnGizmo.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.toggleGizmo();
			};

			const sliderSkeletonSize = getSlider('Thickness', 1, 5, step, initParam.thickness);
			this.divUILeft.appendChild(sliderSkeletonSize.div);
			sliderSkeletonSize.slider.oninput = () => {
				const value = parseFloat(sliderSkeletonSize.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setSizeSkeletonParametricHC(value);
			};

			const sliderRadiusCamera = getSlider('Camera size', 0.5, 2, step, initParam.radiusCamera);
			this.divUILeft.appendChild(sliderRadiusCamera.div);
			sliderRadiusCamera.slider.oninput = () => {
				const value = parseFloat(sliderRadiusCamera.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setSizeCameraHC(value);
			};

			const sliderRollingPanel = getSlider('Rolling Panel', 0.5, 2, step, initParam.WallUnit.height);
			this.divUILeft.appendChild(sliderRollingPanel.div);
			sliderRollingPanel.slider.oninput = () => {
				const value = parseFloat(sliderRollingPanel.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setSizeRollingPanel(value);
			};
			const sliderGapRollingPanel = getSlider('Rolling Panel Gap', 0.1, 1, step, initParam.WallUnit.heightGap);
			this.divUILeft.appendChild(sliderGapRollingPanel.div);
			sliderGapRollingPanel.slider.oninput = () => {
				const value = parseFloat(sliderGapRollingPanel.slider.value);
				// console.log(value);
				this.view.solution.appCore.common.commandHypercubeParametric.setSizeGapRollingPanel(value);
			};

			const sliderGridFloor = getSlider('Floor Scale', 0.5, 2, step, initParam.radiusCamera);
			this.divUILeft.appendChild(sliderGridFloor.div);
			sliderGridFloor.slider.oninput = () => {
				const value = parseFloat(sliderGridFloor.slider.value);
				this.view.solution.appCore.common.commandHypercubeParametric.setSizeGridFloor(value);
			};

			let xRayMode = true;
			const divBtnXRayMode = document.createElement('button');
			this.divUILeft.appendChild(divBtnXRayMode);
			divBtnXRayMode.style.marginTop = '15px';
			divBtnXRayMode.style.width = this.width;
			divBtnXRayMode.textContent = 'Show/Hide X-Ray';
			divBtnXRayMode.style.fontSize = '10px';
			divBtnXRayMode.onclick = () => {
				// if (xRayMode) {
				this.view.solution.appCore.common.commandHypercubeParametric.toggleXrayParametricModel(xRayMode);
				// } else {
				// 	this.view.solution.appCore.common.commandHypercubeParametric.hideHypercubeStatic();
				// }
				xRayMode = !xRayMode;
			};

			this.divUILeft.appendChild(getDivider());

			let clippingMode = false;
			const divBtnClipping = document.createElement('button');
			this.divUILeft.appendChild(divBtnClipping);
			divBtnClipping.style.marginTop = '15px';
			divBtnClipping.style.width = this.width;
			divBtnClipping.textContent = 'Show/Hide Clipping planes';
			divBtnClipping.style.fontSize = '10px';
			divBtnClipping.onclick = () => {
				// if (clippingMode) {
				this.view.solution.appCore.common.commandHypercubeParametric.toggleClippingMode(clippingMode);
				// } else {
				// 	this.view.solution.appCore.common.commandHypercubeParametric.hideHypercubeStatic();
				// }
				clippingMode = !clippingMode;
			};

			const clippingDefault = 60;
			const sliderYSlipping = getSlider('Clipping Y', -20, 30, step, clippingDefault);
			this.divUILeft.appendChild(sliderYSlipping.div);
			sliderYSlipping.slider.oninput = () => {
				const value = parseFloat(sliderYSlipping.slider.value);
				this.view.solution.appCore.common.commandHypercubeParametric.setClippingYParametricHC(value);
			};

			const sliderXSlipping = getSlider('Clipping X', -20, 30, step, clippingDefault);
			this.divUILeft.appendChild(sliderXSlipping.div);
			sliderXSlipping.slider.oninput = () => {
				const value = parseFloat(sliderXSlipping.slider.value);
				this.view.solution.appCore.common.commandHypercubeParametric.setClippingXParametricHC(value);
			};
			const sliderZSlipping = getSlider('Clipping Z', -20, 30, step, clippingDefault);
			this.divUILeft.appendChild(sliderZSlipping.div);
			sliderZSlipping.slider.oninput = () => {
				const value = parseFloat(sliderZSlipping.slider.value);
				this.view.solution.appCore.common.commandHypercubeParametric.setClippingZParametricHC(value);
			};

			this.divUILeft.appendChild(getDivider());

			const divBtnOptimization = document.createElement('button');
			this.divUILeft.appendChild(divBtnOptimization);
			divBtnOptimization.style.marginTop = '15px';
			divBtnOptimization.style.width = this.width;
			divBtnOptimization.textContent = 'Optimization';
			divBtnOptimization.style.fontSize = '10px';
			divBtnOptimization.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.runOptimization();
			};

			const label = document.createElement('label');
			label.textContent = 'Target Volume: ';
			label.setAttribute('for', 'numberInput');
			label.style.fontSize = '11px';
			this.divUILeft.appendChild(label);

			const input = document.createElement('input');
			input.type = 'number';
			input.id = 'numberInput';
			input.name = 'numberInput';
			input.style.width = '70px';
			input.min = 0;
			input.max = 9999999;
			input.step = 1;
			input.value = 20000;
			input.onkeyup = () => {
				// console.log(input.value);
				this.view.solution.appCore.common.commandHypercubeParametric.setVolumeOptimization(+input.value);
			};
			this.divUILeft.appendChild(input);

			const divBtnDoorOuter = document.createElement('button');
			this.divUILeft.appendChild(divBtnDoorOuter);
			divBtnDoorOuter.style.marginTop = '15px';
			divBtnDoorOuter.style.width = this.width;
			divBtnDoorOuter.textContent = 'open door ';
			divBtnDoorOuter.style.fontSize = '10px';
			divBtnDoorOuter.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.openOuter();
			};

			const divBtnAddons = document.createElement('button');
			this.divUILeft.appendChild(divBtnAddons);
			divBtnAddons.style.marginTop = '15px';
			divBtnAddons.style.width = this.width;
			divBtnAddons.textContent = 'Toggle addon';
			divBtnAddons.style.fontSize = '10px';
			divBtnAddons.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.toggleAddon();
			};

			minParam = 0;
			maxParam = 100;
			scaleParam = 0.01;
			const debuggerA = getSlider('roughness', minParam, maxParam);
			debuggerA.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerA.div);
			debuggerA.slider.oninput = () => {
				const value = parseFloat(debuggerA.slider.value) * scaleParam;
				this.view.solution.appCore.common.roughness(value);
			};
			const debuggerB = getSlider('metalness', minParam, maxParam);
			debuggerB.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerB.div);
			debuggerB.slider.oninput = () => {
				const value = parseFloat(debuggerB.slider.value) * scaleParam;
				this.view.solution.appCore.common.metalness(value);
			};

			const debuggerC = getSlider('roughness', minParam, maxParam);
			debuggerC.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerC.div);
			debuggerC.slider.oninput = () => {
				const value = parseFloat(debuggerC.slider.value) * scaleParam;
				this.view.solution.appCore.common.roughness(value);
			};
			const debuggerD = getSlider('metalness', minParam, maxParam);
			debuggerD.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerD.div);
			debuggerD.slider.oninput = () => {
				const value = parseFloat(debuggerD.slider.value) * scaleParam;
				this.view.solution.appCore.common.metalness(value);
			};

			const debuggerF = getSlider('debugger Z', minParam, maxParam);
			debuggerF.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerF.div);
			debuggerF.slider.oninput = () => {
				const value = parseFloat(debuggerF.slider.value);
				this.view.solution.appCore.common.debuggerZ(value);
			};

			const debuggerR = getSlider('Rotation', minParam, maxParam);
			debuggerR.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerR.div);
			debuggerR.slider.oninput = () => {
				const value = parseFloat(debuggerR.slider.value);
				this.view.solution.appCore.common.debuggerRotation(value);
			};
			const debuggerRL = getSlider('Rotation', minParam, maxParam);
			debuggerRL.slider.defaultValue = '0.0';
			this.divUILeft.appendChild(debuggerRL.div);
			debuggerRL.slider.oninput = () => {
				const value = parseFloat(debuggerRL.slider.value);
				this.view.solution.appCore.common.debuggerRotationLaser(value);
			};

			const divBtnGetParameters = document.createElement('button');
			this.divUILeft.appendChild(divBtnGetParameters);
			divBtnGetParameters.style.marginTop = '15px';
			divBtnGetParameters.style.width = this.width;
			divBtnGetParameters.textContent = 'Download the parameters';
			divBtnGetParameters.style.fontSize = '10px';
			divBtnGetParameters.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.downloadParameter();
			};

			const divBtnGetP = document.createElement('button');
			this.divUILeft.appendChild(divBtnGetP);
			divBtnGetP.style.marginTop = '15px';
			divBtnGetP.style.width = this.width;
			divBtnGetP.textContent = 'Click';
			divBtnGetP.style.fontSize = '10px';
			divBtnGetP.onclick = () => {
				this.view.solution.appCore.common.commandHypercubeParametric.openSlidingDoor();
			};
		}
	}
}
