import * as THREE from 'three';
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader.js';
import { PMREMGenerator } from 'three';

import { RendererCore } from '..';
import { isWebGLRenderer, isTexture } from '../../utils/ThreeUtils';

export class HDRIWrapper {
	public threeCore: RendererCore;

	public envMap: THREE.Texture | undefined;
	private currentEnvironmentMap: THREE.Texture | undefined;

	constructor(threeCore: RendererCore) {
		this.threeCore = threeCore;
	}
	public async init() {
		const hdrName = this.threeCore.isPerformanceMode ? 'bridge-smaller.hdr' : 'bridgeSmall.hdr';

		await this.updateHDRI(hdrName);
	}
	public async updateHDRI(name: string = '', zUp = false) {
		try {
			if (!name) {
				if (this.currentEnvironmentMap) {
					this.currentEnvironmentMap.dispose();
					this.currentEnvironmentMap = undefined;
				}
				this.envMap = undefined;

				this.threeCore.scene.environment = null;
				this.threeCore.scene.background = null;

				this.threeCore.renderForce?.();
				return;
			}

			// const path = process.env.PUBLIC_URL + '/static/data/model/map/' + name;
			const loader = new RGBELoader();
			const path = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/' + name;

			const hdrEquirect = await loader.loadAsync(path);
			hdrEquirect.mapping = THREE.EquirectangularReflectionMapping;

			const renderer = this.threeCore.renderer;
			let envMap: THREE.Texture;

			if (isWebGLRenderer(renderer)) {
				const pmremGenerator = new PMREMGenerator(renderer);
				pmremGenerator.compileEquirectangularShader();

				envMap = pmremGenerator.fromEquirectangular(hdrEquirect).texture;

				pmremGenerator.dispose();
				hdrEquirect.dispose();
			} else {
				// WebGPU: PMREMGenerator not support
				envMap = hdrEquirect;
			}

			this.envMap = envMap;
			this.currentEnvironmentMap = envMap;

			this.threeCore.scene.environment = envMap;

			this.threeCore.scene.background = isWebGLRenderer(renderer) && isTexture(envMap) ? envMap : new THREE.Color(0xffffff);

			this.threeCore.renderForce();
		} catch (error) {
			console.error('HDRI, fail to load:', error);
		}
	}
	public toggleHDRIBackground(value: boolean) {
		const renderer = this.threeCore.renderer;

		if (value && isTexture(this.envMap) && isWebGLRenderer(renderer)) {
			this.threeCore.scene.background = this.envMap;
		} else {
			this.threeCore.scene.background = null;
		}
	}
}
